function InvokeDom([string]$WsUrl,[bool]$AllowClick){$node=Get-Command node.exe -ErrorAction SilentlyContinue;if(!$node){$node=Get-Command node -ErrorAction Stop};$js=Join-Path $env:TEMP ('flow-screen-'+[guid]::NewGuid().ToString('N')+'.mjs');$code=@'
const wsUrl=process.argv[2],allowClick=process.argv[3]==='1';
function c(url){return new Promise((resolve,reject)=>{const ws=new WebSocket(url);let id=0,p=new Map();ws.onopen=()=>resolve({ws,send:(m,params={})=>new Promise((res,rej)=>{const n=++id;p.set(n,{res,rej});ws.send(JSON.stringify({id:n,method:m,params}));})});ws.onerror=reject;ws.onmessage=e=>{let x;try{x=JSON.parse(e.data)}catch{return};if(x.id&&p.has(x.id)){const q=p.get(x.id);p.delete(x.id);x.error?q.rej(new Error(JSON.stringify(x.error))):q.res(x.result)}}})}
const x=await c(wsUrl);try{const expr=`(()=>{const norm=s=>String(s||'').trim().replace(/\\s+/g,' ');const controls=[...document.querySelectorAll('button,[role="button"],a,input[type="submit"]')].filter(e=>{const r=e.getBoundingClientRect();return r.width&&r.height&&!e.disabled});const items=controls.map((e,i)=>({i,text:norm(e.innerText||e.textContent||e.value||e.getAttribute('aria-label')||''),tag:e.tagName,href:e.href||''}));const inputs=[...document.querySelectorAll('textarea,input[type="text"],[contenteditable="true"],[role="textbox"]')].filter(e=>{const r=e.getBoundingClientRect();return r.width&&r.height&&!e.disabled}).map(e=>({tag:e.tagName,placeholder:e.getAttribute('placeholder')||'',aria:e.getAttribute('aria-label')||'',value:('value'in e?e.value:e.innerText||'').slice(0,300)}));const text=(document.body?.innerText||'').slice(0,10000);const url=location.href;let state='OTHER';if(/accounts\\.google\\.com/i.test(url))state='GOOGLE_LOGIN';else if(/labs\\.google\/fx\/tools\/flow/i.test(url))state=inputs.length?'FLOW_WORKSPACE':'FLOW_LANDING_OR_CONSENT';else if(/labs\\.google/i.test(url))state='GOOGLE_LABS_INTERMEDIATE';let clicked=null;if(${allowClick?'true':'false'}&&state!=='FLOW_WORKSPACE'){const allow=[/^계속$/i,/^continue$/i,/^동의$/i,/^agree$/i,/^허용$/i,/^allow$/i,/^시작하기$/i,/^get started$/i,/^try flow$/i,/^open flow$/i,/^확인$/i,/^confirm$/i,/프로젝트 열기|이어하기|recent|resume/i,/새 프로젝트|new project|create project/i];for(const it of items){if(allow.some(rx=>rx.test(it.text))){try{controls[it.i].click();clicked=it;break}catch{}}}}return {url,title:document.title,state,inputs,buttons:items.slice(0,120),bodyText:text,clicked,passwordPrompt:!!document.querySelector('input[type="password"]'),emailPrompt:!!document.querySelector('input[type="email"]')};})()`;const r=await x.send('Runtime.evaluate',{expression:expr,returnByValue:true,awaitPromise:true,userGesture:true});console.log(JSON.stringify(r.result?.value||{}));}finally{try{x.ws.close()}catch{};setTimeout(()=>process.exit(0),30)}
'@;Set-Content -LiteralPath $js -Value $code -Encoding UTF8;try{$psi=New-Object Diagnostics.ProcessStartInfo;$psi.FileName=$node.Source;$psi.UseShellExecute=$false;$psi.CreateNoWindow=$true;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true;$psi.Arguments=('"'+$js+'" "'+$WsUrl+'" '+$(if($AllowClick){'1'}else{'0'}));$p=New-Object Diagnostics.Process;$p.StartInfo=$psi;[void]$p.Start();$o=$p.StandardOutput.ReadToEndAsync();$e=$p.StandardError.ReadToEndAsync();if(-not $p.WaitForExit(15000)){try{Stop-Process -Id $p.Id -Force}catch{};throw 'FLOW_CDP_DOM_TIMEOUT'};$raw=$o.Result.Trim();if(!$raw){throw ('FLOW_CDP_DOM_EMPTY:'+ $e.Result.Trim())};return (($raw -split "`r?`n")[-1]|ConvertFrom-Json)}finally{Remove-Item $js -Force -ErrorAction SilentlyContinue}}
$central=FindCentral;if(!$central){throw 'CENTRAL_DRIVE_ROOT_NOT_FOUND'};$normalBefore=@(NormalRoots)
if($CurrentScreenOnly){$pages=@(Pages);$page=$pages|Where-Object{([string]$_.url) -match 'labs\.google|accounts\.google'}|Select-Object -First 1;if(!$page){throw 'CDP_FLOW_PAGE_NOT_FOUND_ON_CURRENT_SCREEN'};$scan=InvokeDom ([string]$page.webSocketDebuggerUrl) $false;$extTargets=@($pages|Where-Object{([string]$_.url) -like 'chrome-extension://*'}|ForEach-Object{[ordered]@{url=[string]$_.url;title=[string]$_.title}});$normalAfter=@(NormalRoots);$missing=@($normalBefore|Where-Object{$normalAfter -notcontains $_});$input=@($scan.inputs)|Select-Object -First 1;$ok=[bool]([string]$scan.state -eq 'FLOW_WORKSPACE' -and $input -and $missing.Count -eq 0);$result=[ordered]@{ok=$ok;action='FLOW_CURRENT_SCREEN_CDP_READONLY';version=$Version;state=[string]$scan.state;pageUrl=[string]$scan.url;pageTitle=[string]$scan.title;inputFound=[bool]$input;input=$input;buttons=@($scan.buttons);extensionTargets=$extTargets;flowWorkspaceTextObserved=([string]$scan.bodyText -match '무엇을 만들고 싶으신가요|Flow');normalChromeUntouched=($missing.Count -eq 0);generateClicked=$false;creditSpend=$false;readOnly=$true;checkedAt=(Get-Date).ToString('o')};$dir=Join-Path $central 'Runtime_Readback\Flow_Bridge_Direct';New-Item -ItemType Directory -Force -Path $dir|Out-Null;$path=Join-Path $dir 'FLOW_CURRENT_SCREEN_CDP_READONLY.json';$result|ConvertTo-Json -Depth 40|Set-Content -LiteralPath $path -Encoding UTF8;$result['resultPath']=$path;$result|ConvertTo-Json -Depth 40 -Compress;exit $(if($ok){0}else{2})}
$FlowExt=FindFlowExt;if(!$FlowExt){throw 'FLOW_EXTENSION_PATH_NOT_FOUND'};$chrome=Get-ChildItem -LiteralPath $CftRoot -Recurse -Filter chrome.exe -File -ErrorAction Stop|Sort-Object FullName -Descending|Select-Object -First 1;if(!$chrome){throw 'CFT_CHROME_NOT_FOUND'};StopDedicated;$args=@("--user-data-dir=$UserData",'--profile-directory=Default','--new-window','--no-first-run','--no-default-browser-check','--disable-session-crashed-bubble',("--load-extension=$FlowExt"),("--remote-debugging-port=$DebugPort"),'--remote-debugging-address=127.0.0.1',$FlowUrl);Start-Process -FilePath $chrome.FullName -ArgumentList $args -WorkingDirectory $chrome.Directory.FullName|Out-Null
$deadline=(Get-Date).AddSeconds($(if($NavigateWorkspace){$TimeoutSeconds}else{30}));$history=@();$final=$null;$credentialRequired=$false;while((Get-Date)-lt $deadline){$pages=@(Pages);$page=$pages|Where-Object{([string]$_.url) -match 'accounts\.google\.com|labs\.google'}|Select-Object -First 1;if(!$page){Start-Sleep -Milliseconds 600;continue};$scan=InvokeDom ([string]$page.webSocketDebuggerUrl) ([bool]$NavigateWorkspace);$history += [ordered]@{at=(Get-Date).ToString('o');url=[string]$scan.url;title=[string]$scan.title;state=[string]$scan.state;inputCount=@($scan.inputs).Count;clicked=$scan.clicked};$final=$scan;if($NavigateWorkspace -and [string]$scan.state -eq 'FLOW_WORKSPACE' -and @($scan.inputs).Count){break};if($NavigateWorkspace -and [string]$scan.state -eq 'GOOGLE_LOGIN' -and ($scan.passwordPrompt -or $scan.emailPrompt)){$credentialRequired=$true;break};if(-not $NavigateWorkspace -and [string]$scan.state -eq 'FLOW_WORKSPACE'){break};Start-Sleep -Seconds 2};$normalAfter=@(NormalRoots);$missing=@($normalBefore|Where-Object{$normalAfter -notcontains $_});if($NavigateWorkspace){$ok=[bool]($final -and [string]$final.state -eq 'FLOW_WORKSPACE' -and @($final.inputs).Count -and $missing.Count -eq 0);$result=[ordered]@{ok=$ok;action='FLOW_LOGIN_CONSENT_TO_WORKSPACE';version=$Version;workspaceReached=$ok;credentialEntryRequired=$credentialRequired;finalState=$(if($final){[string]$final.state}else{'NO_PAGE'});pageUrl=$(if($final){[string]$final.url}else{''});inputs=$(if($final){@($final.inputs)}else{@()});history=$history;normalChromeUntouched=($missing.Count -eq 0);generateClicked=$false;creditSpend=$false;credentialEnteredByAutomation=$false;checkedAt=(Get-Date).ToString('o')};$dir=Join-Path $central 'Runtime_Readback\Flow_Bridge_Direct';New-Item -ItemType Directory -Force -Path $dir|Out-Null;$path=Join-Path $dir 'FLOW_LOGIN_CONSENT_TO_WORKSPACE.json';$result|ConvertTo-Json -Depth 40|Set-Content -LiteralPath $path -Encoding UTF8;$result|ConvertTo-Json -Depth 40 -Compress;exit $(if($ok){0}elseif($credentialRequired){3}else{2})};if(-not $final -or [string]$final.state -ne 'FLOW_WORKSPACE'){throw 'FLOW_WORKSPACE_NOT_REACHED_FOR_CREDIT_READBACK'};$creditLines=@(([string]$final.bodyText -split "`r?`n")|Where-Object{$_ -match '(?i)credit|credits|크레딧'}|Select-Object -First 80);$emails=@([regex]::Matches([string]$final.bodyText,'[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}','IgnoreCase')|ForEach-Object{$_.Value}|Select-Object -Unique);StopDedicated;$args2=@("--user-data-dir=$UserData",'--profile-directory=Default','--new-window','--no-first-run','--no-default-browser-check');if(Test-Path -LiteralPath (Join-Path $NotebookExt 'manifest.json')){$args2+=("--load-extension=$NotebookExt")};$args2+=$NotebookFront;Start-Process -FilePath $chrome.FullName -ArgumentList $args2|Out-Null;$result=[ordered]@{ok=$true;action='FLOW_APPROVED_ACCOUNT_CREDIT_READONLY';emails=$emails;creditLines=$creditLines;generateClicked=$false;creditSpend=$false;checkedAt=(Get-Date).ToString('o')};$result|ConvertTo-Json -Depth 20 -Compress;exit 0